def transform(grid):
    a = [row[:] for row in grid]
    background = Counter(v for row in a for v in row).most_common(1)[0][0]
    points = [(r, c) for r, row in enumerate(a) for c, v in enumerate(row) if v != background]
    if not points:
        return a
    rmin = min(r for r, c in points)
    rmax = max(r for r, c in points)
    cmin = min(c for r, c in points)
    cmax = max(c for r, c in points)

    def mark(r, c):
        if a[r][c] == background:
            a[r][c] = 2

    # Complete the outer rectangle. Internal horizontal runs of at least
    # three marked cells indicate a divider between adjoining rectangles.
    for r in range(rmin, rmax + 1):
        run = longest = 0
        for c in range(len(grid[0])):
            if grid[r][c] != background:
                run += 1
                longest = max(longest, run)
            else:
                run = 0
        if r in (rmin, rmax) or longest >= 3:
            for c in range(cmin, cmax + 1):
                mark(r, c)

    for c in (cmin, cmax):
        for r in range(rmin, rmax + 1):
            mark(r, c)
